INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (101, 101, 'Chính Sách & Điều Kiện Sử Dụng: Đệ Nhất - Buffet Chay Buổi Tối Cao Cấp Mừng Lễ Vu Lan', $BODY$<div class="tab-pane active visible-sm visible-xs visible-md" id="dieu-kien">
        <div class="block__header  clearfix">
            <h3 class="block__title">Điều kiện sử dụng</h3>
        </div>
        <div class="block__content clearfix">
            <div class="wysiwyg">
<p style="text-align:justify">- Thời hạn sử dụng voucher: <strong>từ 22/08/2026 đến 22/11/2026.</strong></p>

<p style="text-align:justify">- Địa điểm sử dụng voucher: <strong>Khu Hoa Vi&ecirc;n Hồ Bơi -&nbsp;Kh&aacute;ch sạn Đệ Nhất</strong> &ndash; 18 Ho&agrave;ng Việt, Phường T&acirc;n Sơn Nhất, Tp.HCM. Hotline hỗ trợ: ĐT: 0919 898 257 - 028 3844 1199 &ndash; 028 3846 2944.</p>

<p style="text-align:justify"><strong>- Voucher &aacute;p dụng cho: Buffet chay cao cấp&nbsp;tinh hoa hơn 50 m&oacute;n chay (Gi&aacute; v&eacute; đ&atilde; bao gồm trọn g&oacute;i quầy line nước uống v&agrave; m&oacute;n tr&aacute;ng miệng).&nbsp;Tham khảo menu <a href="https://oms.hotdeal.vn/images/editors/sources/000371326374/2aOboQrREbzM2SZvyMAyZlmndRPb1caZxCFx1sn2.jpg" rel="nofollow" target="_blank" rel="nofollow">tại đ&acirc;y</a>.</strong></p>

<p style="text-align:justify"><span style="color:#FF0000"><strong>-&nbsp;Thời gian &aacute;p dụng v&agrave;o c&aacute;c ng&agrave;y chay m&ugrave;ng 1, 14, 15 &acirc;m lịch h&agrave;ng th&aacute;ng.&nbsp;</strong></span></p>

<p style="text-align:justify">- Khung giờ phục vụ buffet:&nbsp;18h00 &ndash; 21h00.</p>

<p style="text-align:justify"><strong>- Quy định sử dụng: &Aacute;p dụng 01 voucher/ 01 người/ 01 suất buffet chay (Kh&aacute;ch h&agrave;ng kh&ocirc;ng cần b&ugrave; th&ecirc;m bất kỳ chi ph&iacute; n&agrave;o).</strong></p>

<p style="text-align:justify"><strong>- Ch&iacute;nh s&aacute;ch thuế &amp; h&oacute;a đơn: Gi&aacute; tr&ecirc;n voucher đ&atilde; bao gồm thuế VAT.&nbsp;Kh&aacute;ch sạn sẽ xuất h&oacute;a đơn t&agrave;i ch&iacute;nh trực tiếp khi kh&aacute;ch h&agrave;ng c&oacute; y&ecirc;u cầu.</strong></p>

<p style="text-align:justify">- Quy định đặt chỗ trước: Qu&yacute; kh&aacute;ch vui l&ograve;ng li&ecirc;n hệ Hotline đặt b&agrave;n trước&nbsp;khi đến.</p>

<p style="text-align:justify"><strong>- Đối với trẻ em: </strong></p>

<p style="text-align:justify">+ Dưới 1m2: thanh to&aacute;n trực tiếp tại nh&agrave; h&agrave;ng 129.000 vnđ/01 b&eacute;.</p>

<p style="text-align:justify">+ Từ 1m2: t&iacute;nh như v&eacute; người lớn.</p>

<p style="text-align:justify">- Một kh&aacute;ch h&agrave;ng được mua nhiều phiếu. Kh&ocirc;ng &aacute;p dụng cho mang về.</p>

<p style="text-align:justify">- Kh&ocirc;ng &aacute;p dụng đồng thời với c&aacute;c chương tr&igrave;nh khuyến m&atilde;i kh&aacute;c.</p>

<p style="text-align:justify">- Phiếu kh&ocirc;ng c&oacute; gi&aacute; trị quy đổi th&agrave;nh tiền mặt, kh&ocirc;ng trả lại tiền thừa.</p>

<p style="text-align:justify"><strong>- Thanh to&aacute;n online nhận ngay voucher điện tử.</strong></p>
</div>
        </div>$BODY$, 'POLICY', 'ACTIVE');
INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (102, 101, 'Trải Nghiệm Dịch Vụ & Điểm Nổi Bật: Đệ Nhất - Buffet Chay Buổi Tối Cao Cấp Mừng Lễ Vu Lan', $BODY$<div class="tab-pane active first" id="chi-tiet">
        <div class="block__header  clearfix">
            <h3 class="block__title">Thông tin chi tiết</h3>
        </div>
        <div class="block__content clearfix">
            <div class="wysiwyg">
    <p style="text-align:justify">M&ugrave;a Vu Lan l&agrave; dịp để mỗi người hướng về cội nguồn, b&agrave;y tỏ l&ograve;ng biết ơn v&agrave; hiếu k&iacute;nh đối với &ocirc;ng b&agrave;, cha mẹ. Một bữa cơm chay thanh đạm trong kh&ocirc;ng gian y&ecirc;n b&igrave;nh kh&ocirc;ng chỉ l&agrave; lựa chọn tốt cho sức khỏe m&agrave; c&ograve;n l&agrave; c&aacute;ch để cả gia đ&igrave;nh c&ugrave;ng qu&acirc;y quần, sẻ chia những khoảnh khắc &yacute; nghĩa. Buffet Chay Cao Cấp tại Khu Hoa Vi&ecirc;n Hồ Bơi &ndash; Kh&aacute;ch sạn Đệ Nhất sẽ mang đến h&agrave;nh tr&igrave;nh thưởng thức hơn 50 m&oacute;n chay tinh tế trong kh&ocirc;ng gian xanh m&aacute;t, sang trọng, gi&uacute;p m&ugrave;a Vu Lan th&ecirc;m trọn vẹn v&agrave; ấm &aacute;p.</p>

<p style="text-align:justify">&nbsp;</p>

<p style="text-align:center"><img class="lazy" src="data:image/gif;base64,R0lGODlhAQABAIAAAMLCwgAAACH5BAAAAAAALAAAAAABAAEAAAICRAEAOw==" data-src-mobile="" data-original="https://oms.hotdeal.vn/images/editors/sources/000371326374/371326-371326-body(21).jpg" style="text-align:center" /></p>

<p style="text-align:center"><br />
<img class="lazy" src="data:image/gif;base64,R0lGODlhAQABAIAAAMLCwgAAACH5BAAAAAAALAAAAAABAAEAAAICRAEAOw==" data-src-mobile="" data-original="https://oms.hotdeal.vn/images/editors/sources/000371326374/371326-371326-body(4).jpg" /></p>

<p style="text-align:center">&nbsp;</p>

<p style="text-align:center"><img class="lazy" src="data:image/gif;base64,R0lGODlhAQABAIAAAMLCwgAAACH5BAAAAAAALAAAAAABAAEAAAICRAEAOw==" data-src-mobile="" data-original="https://oms.hotdeal.vn/images/editors/sources/000371326374/371326-371326-body(6).jpg" /></p>

<p style="text-align:center">&nbsp;</p>

<p style="text-align:center"><img class="lazy" src="data:image/gif;base64,R0lGODlhAQABAIAAAMLCwgAAACH5BAAAAAAALAAAAAABAAEAAAICRAEAOw==" data-src-mobile="" data-original="https://oms.hotdeal.vn/images/editors/sources/000371326374/371326-371326-body(7).jpg" style="text-align:center" /></p>

<p style="text-align:justify">&nbsp;</p>

<p style="text-align:center"><img class="lazy" src="data:image/gif;base64,R0lGODlhAQABAIAAAMLCwgAAACH5BAAAAAAALAAAAAABAAEAAAICRAEAOw==" data-src-mobile="" data-original="https://oms.hotdeal.vn/images/editors/sources/000371326374/371326-371326-body(9).jpg" style="text-align:center" /></p>

<p style="text-align:center"><br />
<img class="lazy" src="data:image/gif;base64,R0lGODlhAQABAIAAAMLCwgAAACH5BAAAAAAALAAAAAABAAEAAAICRAEAOw==" data-src-mobile="" data-original="https://oms.hotdeal.vn/images/editors/sources/000371326374/371326-371326-body(8).jpg" style="text-align:center" /></p>

<p style="text-align:center">&nbsp;</p>

<p style="text-align:justify">Đến với Buffet Chay Cao Cấp tại Kh&aacute;ch sạn Đệ Nhất, thực kh&aacute;ch sẽ được thưởng thức hơn 50 m&oacute;n chay đặc sắc được chế biến từ những nguy&ecirc;n liệu tươi ngon như rau củ theo m&ugrave;a, nấm, đậu hũ, t&agrave;u hũ ky, ngũ cốc v&agrave; c&aacute;c loại thực phẩm chay cao cấp. Mỗi m&oacute;n ăn được đầu bếp chăm ch&uacute;t từ hương vị đến c&aacute;ch tr&igrave;nh b&agrave;y, mang đến trải nghiệm ẩm thực tinh tế, thanh đạm nhưng vẫn hấp dẫn.</p>

<p style="text-align:justify">&nbsp;</p>

<p style="text-align:center"><img class="lazy" src="data:image/gif;base64,R0lGODlhAQABAIAAAMLCwgAAACH5BAAAAAAALAAAAAABAAEAAAICRAEAOw==" data-src-mobile="" data-original="https://oms.hotdeal.vn/images/editors/sources/000371326374/371326-371326-body(33).jpg" style="text-align:center" /></p>

<p style="text-align:center"><br />
<img class="lazy" src="data:image/gif;base64,R0lGODlhAQABAIAAAMLCwgAAACH5BAAAAAAALAAAAAABAAEAAAICRAEAOw==" data-src-mobile="" data-original="https://oms.hotdeal.vn/images/editors/sources/000371326374/371326-371326-body(32).jpg" style="text-align:center" /></p>

<p style="text-align:center">&nbsp;</p>

<p style="text-align:center"><img class="lazy" src="data:image/gif;base64,R0lGODlhAQABAIAAAMLCwgAAACH5BAAAAAAALAAAAAABAAEAAAICRAEAOw==" data-src-mobile="" data-original="https://oms.hotdeal.vn/images/editors/sources/000371326374/371326-371326-body(25).jpg" style="text-align:center" /></p>

<p style="text-align:center"><br />
<img class="lazy" src="data:image/gif;base64,R0lGODlhAQABAIAAAMLCwgAAACH5BAAAAAAALAAAAAABAAEAAAICRAEAOw==" data-src-mobile="" data-original="https://oms.hotdeal.vn/images/editors/sources/000371326374/371326-371326-body(24).jpg" style="text-align:center" /></p>

<p style="text-align:justify">&nbsp;</p>

<p style="text-align:justify">Thực đơn được bố tr&iacute; đa dạng theo từng quầy, đ&aacute;p ứng khẩu vị của nhiều thực kh&aacute;ch. Mở đầu bữa tiệc l&agrave; c&aacute;c m&oacute;n salad v&agrave; gỏi thanh m&aacute;t như salad Nga, salad thập cẩm, gỏi cuốn, gỏi ng&oacute; sen, gỏi củ hủ dừa&hellip; gi&uacute;p k&iacute;ch th&iacute;ch vị gi&aacute;c v&agrave; c&acirc;n bằng dinh dưỡng.</p>

<p style="text-align:justify">&nbsp;</p>

<p style="text-align:center"><img class="lazy" src="data:image/gif;base64,R0lGODlhAQABAIAAAMLCwgAAACH5BAAAAAAALAAAAAABAAEAAAICRAEAOw==" data-src-mobile="" data-original="https://oms.hotdeal.vn/images/editors/sources/000371326374/371326-371326-body(29).jpg" style="text-align:center" /></p>

<p style="text-align:center">&nbsp;</p>

<p style="text-align:center"><img class="lazy" src="data:image/gif;base64,R0lGODlhAQABAIAAAMLCwgAAACH5BAAAAAAALAAAAAABAAEAAAICRAEAOw==" data-src-mobile="" data-original="https://oms.hotdeal.vn/images/editors/sources/000371326374/371326-371326-body(28).jpg" style="text-align:center" /></p>

<p style="text-align:center">&nbsp;</p>

<p style="text-align:center"><img class="lazy" src="data:image/gif;base64,R0lGODlhAQABAIAAAMLCwgAAACH5BAAAAAAALAAAAAABAAEAAAICRAEAOw==" data-src-mobile="" data-original="https://oms.hotdeal.vn/images/editors/sources/000371326374/371326-371326-body(34).jpg" style="text-align:center" /></p>

<p style="text-align:justify">&nbsp;</p>

<p style="text-align:justify">Tiếp đến l&agrave; khu vực m&oacute;n n&oacute;ng với nhiều lựa chọn hấp dẫn như hủ tiếu &aacute;p chảo, m&igrave; x&agrave;o thập cẩm, cơm chi&ecirc;n Dương Ch&acirc;u, b&aacute;nh x&egrave;o, b&aacute;nh t&ocirc;m, kết hợp c&ugrave;ng c&aacute;c m&oacute;n chi&ecirc;n gi&ograve;n như chả gi&ograve;, ho&agrave;nh th&aacute;nh chi&ecirc;n, củ sen chi&ecirc;n, nấm b&agrave;o ngư chi&ecirc;n v&agrave; c&aacute;c m&oacute;n x&agrave;o, nướng được chế biến đậm đ&agrave;, giữ trọn hương vị tự nhi&ecirc;n của nguy&ecirc;n liệu.</p>

<p style="text-align:center"><br />
<img class="lazy" src="data:image/gif;base64,R0lGODlhAQABAIAAAMLCwgAAACH5BAAAAAAALAAAAAABAAEAAAICRAEAOw==" data-src-mobile="" data-original="https://oms.hotdeal.vn/images/editors/sources/000371326374/371326-371326-body(27).jpg" style="text-align:center" /></p>

<p style="text-align:center"><br />
<img class="lazy" src="data:image/gif;base64,R0lGODlhAQABAIAAAMLCwgAAACH5BAAAAAAALAAAAAABAAEAAAICRAEAOw==" data-src-mobile="" data-original="https://oms.hotdeal.vn/images/editors/sources/000371326374/371326-371326-body(26).jpg" style="text-align:center" /></p>

<p style="text-align:justify">&nbsp;</p>

<p style="text-align:justify">Điểm nhấn của buffet c&ograve;n l&agrave; c&aacute;c m&oacute;n ch&iacute;nh được chế biến c&ocirc;ng phu như sườn chay x&agrave;o chua ngọt, đậu hũ Tứ Xuy&ecirc;n, c&agrave; ri chay ăn k&egrave;m b&aacute;nh m&igrave;, rau củ nấm kho tương... c&ugrave;ng lẩu nấm chua cay n&oacute;ng hổi, mang đến bữa ăn tr&ograve;n vị v&agrave; ấm c&uacute;ng khi thưởng thức c&ugrave;ng gia đ&igrave;nh, bạn b&egrave;.</p>

<p style="text-align:justify">&nbsp;</p>

<p style="text-align:center"><img class="lazy" src="data:image/gif;base64,R0lGODlhAQABAIAAAMLCwgAAACH5BAAAAAAALAAAAAABAAEAAAICRAEAOw==" data-src-mobile="" data-original="https://oms.hotdeal.vn/images/editors/sources/000371326374/371326-371326-body(31).jpg" style="text-align:center" /></p>

<p style="text-align:center">​<br />
<img class="lazy" src="data:image/gif;base64,R0lGODlhAQABAIAAAMLCwgAAACH5BAAAAAAALAAAAAABAAEAAAICRAEAOw==" data-src-mobile="" data-original="https://oms.hotdeal.vn/images/editors/sources/000371326374/371326-371326-body(30).jpg" style="text-align:center" /></p>

<p style="text-align:justify">&nbsp;</p>

<p style="text-align:center"><img class="lazy" src="data:image/gif;base64,R0lGODlhAQABAIAAAMLCwgAAACH5BAAAAAAALAAAAAABAAEAAAICRAEAOw==" data-src-mobile="" data-original="https://oms.hotdeal.vn/images/editors/sources/000371326374/371326-371326-body(15).jpg" style="text-align:center" /></p>

<p style="text-align:justify">&nbsp;</p>

<p style="text-align:justify">B&ecirc;n cạnh đ&oacute;, thực kh&aacute;ch c&ograve;n c&oacute; thể thưởng thức c&aacute;c m&oacute;n s&uacute;p bổ dưỡng, đa dạng c&aacute;c loại ch&egrave;, b&aacute;nh truyền thống, rau c&acirc;u v&agrave; tr&aacute;i c&acirc;y tươi theo m&ugrave;a, tạo n&ecirc;n một bữa tiệc chay trọn vẹn từ khai vị đến tr&aacute;ng miệng.</p>

<p style="text-align:justify">&nbsp;</p>

<p style="text-align:center"><img class="lazy" src="data:image/gif;base64,R0lGODlhAQABAIAAAMLCwgAAACH5BAAAAAAALAAAAAABAAEAAAICRAEAOw==" data-src-mobile="" data-original="https://oms.hotdeal.vn/images/editors/sources/000371326374/371326-371326-body(23).jpg" /></p>

<p style="text-align:center"><br />
<img class="lazy" src="data:image/gif;base64,R0lGODlhAQABAIAAAMLCwgAAACH5BAAAAAAALAAAAAABAAEAAAICRAEAOw==" data-src-mobile="" data-original="https://oms.hotdeal.vn/images/editors/sources/000371326374/371326-371326-body(19).jpg" /></p>

<p style="text-align:center">&nbsp;</p>

<p style="text-align:center"><img class="lazy" src="data:image/gif;base64,R0lGODlhAQABAIAAAMLCwgAAACH5BAAAAAAALAAAAAABAAEAAAICRAEAOw==" data-src-mobile="" data-original="https://oms.hotdeal.vn/images/editors/sources/000371326374/371326-371326-body(16).jpg" style="text-align:center" /></p>

<p style="text-align:justify">&nbsp;</p>

