INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (103, 102, 'Chính Sách & Điều Kiện Sử Dụng: Đệ Nhất - Buffet Thứ 7 Cuối Tuần Sang Xịn Bên Hồ Bơi', $BODY$<div class="tab-pane active visible-sm visible-xs visible-md" id="dieu-kien">
        <div class="block__header  clearfix">
            <h3 class="block__title">Điều kiện sử dụng</h3>
        </div>
        <div class="block__content clearfix">
            <div class="wysiwyg">
<p style="text-align:justify">- Thời hạn sử dụng voucher: <strong>từ 22/08/2026 đến 22/11/2026.</strong></p>

<p style="text-align:justify">- Địa điểm sử dụng voucher: <strong>Khu Hoa Vi&ecirc;n Hồ Bơi -&nbsp; Kh&aacute;ch sạn Đệ Nhất</strong> &ndash; 18 Ho&agrave;ng Việt, Phường T&acirc;n Sơn Nhất, Tp.HCM. Hotline hỗ trợ: ĐT: 0919 898 257 - 028 3844 1199 &ndash; 028 3846 2944.</p>

<p style="text-align:justify"><strong>- Voucher &aacute;p dụng cho: Buffet cuối tuần b&ecirc;n hồ bơi - Thứ 7 h&agrave;ng tuần với đa dạng hương vị của hơn 40 m&oacute;n đặc sắc, từ hải sản tươi ngon đến c&aacute;c m&oacute;n ăn tinh tế đ&atilde; gồm tr&aacute;ng miệng v&agrave; nước uống như nước ngọt, nước s&acirc;m, nước suối.</strong></p>

<p style="text-align:justify"><strong>- Tham khảo menu <a href="https://oms.hotdeal.vn/images/editors/sources/000371339757/1WUpukj1Aa9TeJHhhDrGyxkZxoJYsUU3JFW7cC4rAFMWPqQRSjBkoOHFHqMyH7nkeyF.jpg" rel="nofollow" target="_blank" rel="nofollow">tại đ&acirc;y</a>.</strong></p>

<p style="text-align:justify">- Khung giờ phục vụ buffet: 18h00 &ndash; 21h00.</p>

<p style="text-align:justify"><strong>- Quy định sử dụng: &Aacute;p dụng 01 voucher/ 01 người/ 01 suất (Kh&aacute;ch h&agrave;ng kh&ocirc;ng cần b&ugrave; th&ecirc;m bất kỳ chi ph&iacute; n&agrave;o).</strong></p>

<p style="text-align:justify"><strong>- Ch&iacute;nh s&aacute;ch thuế &amp; h&oacute;a đơn: Gi&aacute; tr&ecirc;n voucher đ&atilde; bao gồm thuế VAT. Kh&aacute;ch sạn sẽ xuất h&oacute;a đơn t&agrave;i ch&iacute;nh trực tiếp khi kh&aacute;ch h&agrave;ng c&oacute; y&ecirc;u cầu.</strong></p>

<p style="text-align:justify">- Quy định đặt chỗ trước: Qu&yacute; kh&aacute;ch vui l&ograve;ng li&ecirc;n hệ Hotline đặt b&agrave;n trước khi đến.</p>

<p style="text-align:justify"><strong>- Đối với trẻ em: </strong></p>

<p style="text-align:justify">+ Dưới 1m2: thanh to&aacute;n trực tiếp tại nh&agrave; h&agrave;ng 179.000 đ/ 01 b&eacute;.</p>

<p style="text-align:justify">+ Từ 1m2: t&iacute;nh như v&eacute; người lớn.</p>

<p style="text-align:justify">- Một kh&aacute;ch h&agrave;ng được mua nhiều phiếu. Kh&ocirc;ng &aacute;p dụng cho mang về.</p>

<p style="text-align:justify">- Kh&ocirc;ng &aacute;p dụng đồng thời với c&aacute;c chương tr&igrave;nh khuyến m&atilde;i kh&aacute;c.</p>

<p style="text-align:justify">- Phiếu kh&ocirc;ng c&oacute; gi&aacute; trị quy đổi th&agrave;nh tiền mặt, kh&ocirc;ng trả lại tiền thừa.</p>

<p style="text-align:justify"><strong>- Thanh to&aacute;n online nhận ngay voucher điện tử.</strong></p>
</div>
        </div>$BODY$, 'POLICY', 'ACTIVE');
INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (104, 102, 'Trải Nghiệm Dịch Vụ & Điểm Nổi Bật: Đệ Nhất - Buffet Thứ 7 Cuối Tuần Sang Xịn Bên Hồ Bơi', $BODY$<div class="tab-pane active first" id="chi-tiet">
        <div class="block__header  clearfix">
            <h3 class="block__title">Thông tin chi tiết</h3>
        </div>
        <div class="block__content clearfix">
            <div class="wysiwyg">
    <p style="text-align:justify">Giữa kh&ocirc;ng gian hồ bơi xanh m&aacute;t v&agrave; khung cảnh lung linh khi đ&ecirc;m xuống, tiệc buffet hải sản cao cấp tại Kh&aacute;ch sạn Đệ Nhất hứa hẹn mang đến một h&agrave;nh tr&igrave;nh ẩm thực đầy cảm hứng. Với thực đơn hơn 40 m&oacute;n đặc sắc được phục vụ v&agrave;o mỗi tối thứ 7, đ&acirc;y l&agrave; điểm hẹn l&yacute; tưởng để tận hưởng cuối tuần theo c&aacute;ch trọn vẹn nhất.</p>

<p style="text-align:justify">&nbsp;</p>

<p style="text-align:center"><img class="lazy" src="data:image/gif;base64,R0lGODlhAQABAIAAAMLCwgAAACH5BAAAAAAALAAAAAABAAEAAAICRAEAOw==" data-src-mobile="" data-original="https://oms.hotdeal.vn/images/editors/sources/000371339757/371339-371339-body(9).jpg" /></p>

<p style="text-align:center"><br />
<img class="lazy" src="data:image/gif;base64,R0lGODlhAQABAIAAAMLCwgAAACH5BAAAAAAALAAAAAABAAEAAAICRAEAOw==" data-src-mobile="" data-original="https://oms.hotdeal.vn/images/editors/sources/000371339757/371339-371339-body(7).jpg" /></p>

<p style="text-align:center"><br />
<img class="lazy" src="data:image/gif;base64,R0lGODlhAQABAIAAAMLCwgAAACH5BAAAAAAALAAAAAABAAEAAAICRAEAOw==" data-src-mobile="" data-original="https://oms.hotdeal.vn/images/editors/sources/000371339757/371339-371339-body(5).jpg" /></p>

<p style="text-align:center">&nbsp;</p>

<p style="text-align:center"><img class="lazy" src="data:image/gif;base64,R0lGODlhAQABAIAAAMLCwgAAACH5BAAAAAAALAAAAAABAAEAAAICRAEAOw==" data-src-mobile="" data-original="https://oms.hotdeal.vn/images/editors/sources/000371339757/371339-371339-body(6).jpg" style="text-align:center" /></p>

<p style="text-align:center"><br />
<img class="lazy" src="data:image/gif;base64,R0lGODlhAQABAIAAAMLCwgAAACH5BAAAAAAALAAAAAABAAEAAAICRAEAOw==" data-src-mobile="" data-original="https://oms.hotdeal.vn/images/editors/sources/000371339757/371339-371339-body(4).jpg" /></p>

<p style="text-align:center">&nbsp;</p>

<p style="text-align:center"><img class="lazy" src="data:image/gif;base64,R0lGODlhAQABAIAAAMLCwgAAACH5BAAAAAAALAAAAAABAAEAAAICRAEAOw==" data-src-mobile="" data-original="https://oms.hotdeal.vn/images/editors/sources/000371339757/371339-371339-body(8).jpg" style="text-align:center" /></p>

<p style="text-align:center">&nbsp;</p>

<p style="text-align:justify"><strong>Hơn 40 m&oacute;n ăn đặc sắc, đa dạng hương vị</strong></p>

<p style="text-align:justify">Diễn ra v&agrave;o thứ 7 h&agrave;ng tuần, buffet phục vụ hơn 40 m&oacute;n ăn hấp dẫn được chế biến từ nguồn nguy&ecirc;n liệu tươi ngon. Thực kh&aacute;ch sẽ được thưởng thức đa dạng c&aacute;c m&oacute;n salad, khai vị, m&oacute;n n&oacute;ng, m&oacute;n nướng, lẩu, hải sản, m&oacute;n chay c&ugrave;ng nhiều m&oacute;n tr&aacute;ng miệng hấp dẫn, đ&aacute;p ứng khẩu vị của mọi th&agrave;nh vi&ecirc;n trong gia đ&igrave;nh.</p>

<p style="text-align:justify">&nbsp;</p>

<p style="text-align:center"><img class="lazy" src="data:image/gif;base64,R0lGODlhAQABAIAAAMLCwgAAACH5BAAAAAAALAAAAAABAAEAAAICRAEAOw==" data-src-mobile="" data-original="https://oms.hotdeal.vn/images/editors/sources/000371339757/371339-371339-body(19).jpg" /></p>

<p style="text-align:center">&nbsp;</p>

<p style="text-align:center"><img class="lazy" src="data:image/gif;base64,R0lGODlhAQABAIAAAMLCwgAAACH5BAAAAAAALAAAAAABAAEAAAICRAEAOw==" data-src-mobile="" data-original="https://oms.hotdeal.vn/images/editors/sources/000371339757/371339-371339-body(20).jpg" /></p>

<p style="text-align:justify">&nbsp;</p>

<p style="text-align:justify"><strong>Hải sản tươi ngon &ndash; Điểm nhấn của bữa tiệc</strong></p>

<p style="text-align:justify">Quầy hải sản l&agrave; điểm nhấn nổi bật với c&aacute;c m&oacute;n như t&ocirc;m rang muối, s&ograve; nướng, ốc nướng, t&ocirc;m vi&ecirc;n v&agrave; mực vi&ecirc;n nướng được chế biến n&oacute;ng hổi, đậm đ&agrave; hương vị. B&ecirc;n cạnh đ&oacute;, thực kh&aacute;ch c&ograve;n c&oacute; thể thưởng thức c&aacute;c m&oacute;n nướng thơm lừng v&agrave; lựa chọn nước lẩu cua đồng hoặc lẩu chua cay c&ugrave;ng nhiều loại topping phong ph&uacute; như t&ocirc;m, mực, c&aacute; phi l&ecirc;, thịt g&agrave;, thịt heo v&agrave; rau tươi.</p>

<p style="text-align:justify">&nbsp;</p>

<p style="text-align:center"><img class="lazy" src="data:image/gif;base64,R0lGODlhAQABAIAAAMLCwgAAACH5BAAAAAAALAAAAAABAAEAAAICRAEAOw==" data-src-mobile="" data-original="https://oms.hotdeal.vn/images/editors/sources/000371339757/371339-371339-body(18).jpg" style="text-align:center" /></p>

<p style="text-align:center">&nbsp;</p>

<p style="text-align:center"><img class="lazy" src="data:image/gif;base64,R0lGODlhAQABAIAAAMLCwgAAACH5BAAAAAAALAAAAAABAAEAAAICRAEAOw==" data-src-mobile="" data-original="https://oms.hotdeal.vn/images/editors/sources/000371339757/371339-371339-body(11).jpg" style="text-align:center" /></p>

<p style="text-align:center">&nbsp;</p>

<p style="text-align:center"><img class="lazy" src="data:image/gif;base64,R0lGODlhAQABAIAAAMLCwgAAACH5BAAAAAAALAAAAAABAAEAAAICRAEAOw==" data-src-mobile="" data-original="https://oms.hotdeal.vn/images/editors/sources/000371339757/371339-371339-body(26).jpg" style="text-align:center" /><br />
<img class="lazy" src="data:image/gif;base64,R0lGODlhAQABAIAAAMLCwgAAACH5BAAAAAAALAAAAAABAAEAAAICRAEAOw==" data-src-mobile="" data-original="https://oms.hotdeal.vn/images/editors/sources/000371339757/371339-371339-body(25).jpg" style="text-align:center" /></p>

<p style="text-align:center">&nbsp;</p>

