INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (105, 103, 'Chính Sách & Điều Kiện Sử Dụng: Membership Lai Towa - 1 Khách - 7 Ưu Đãi - Tầng 28 Sedona Suites', $BODY$<div class="tab-pane active visible-sm visible-xs visible-md" id="dieu-kien">
        <div class="block__header  clearfix">
            <h3 class="block__title">Điều kiện sử dụng</h3>
        </div>
        <div class="block__content clearfix">
            <div class="wysiwyg">
<p style="text-align:justify">- Thời hạn sử dụng voucher: <strong>từ 31/07/2026 đến 31/07/2027.</strong></p>

<p style="text-align:justify">- Địa điểm sử dụng voucher: <strong>Lai - Towa - Tầng 28 Sedona Suites </strong>(B&ecirc;n cạnh S&agrave;i G&ograve;n Center) 92-94 Nam Kỳ Khởi Nghĩa, Phường S&agrave;i G&ograve;n, TP. Hồ Ch&iacute; Minh - Hotline: 0903 116 038.</p>

<p style="text-align:justify">- Kh&aacute;ch h&agrave;ng cung cấp th&ocirc;ng tin (t&ecirc;n v&agrave; số điện thoại) để k&iacute;ch hoạt thẻ tại thời điểm mua voucher qua số hotline: 0903 116 038. Thẻ chỉ được k&iacute;ch hoạt ng&agrave;y kế tiếp sau khi mua th&agrave;nh c&ocirc;ng.</p>

<p style="text-align:justify">- Kh&aacute;ch h&agrave;ng vui l&ograve;ng li&ecirc;n hệ&nbsp;đặt chỗ trước 24 giờ khi đến theo. Việc đặt b&agrave;n phụ thuộc v&agrave;o t&igrave;nh trạng chỗ trống v&agrave; khả năng phục vụ của nh&agrave; h&agrave;ng.</p>

<p style="text-align:justify"><strong>- Voucher &aacute;p dụng cho Membership Lai Towa chỉ với 1.111.000 VNĐ (Gi&aacute; gốc 2.500.000 VNĐ) - Ưu đ&atilde;i cực sốc&nbsp; - Ngắm trọn view S&agrave;i G&ograve;n về đ&ecirc;m từ tầng 28.</strong></p>

<p style="text-align:justify"><strong>Nội dung ưu đ&atilde;i Membership bao gồm 7 ưu đ&atilde;i sau:</strong></p>

<p style="text-align:justify"><strong>- 01 con vịt quay Bắc Kinh 2 m&oacute;n cho 4&nbsp; người</strong></p>

<p style="text-align:justify"><strong>- 01 set menu m&oacute;n Nhật cho 2 kh&aacute;ch</strong></p>

<p style="text-align:justify"><strong>- 02 suất ăn trưa (m&oacute;n Hoa từ thứ 2 - thứ 6, m&oacute;n Nhật từ thứ 2 - Chủ nhật) d&agrave;nh cho 2 người </strong></p>

<p style="text-align:justify"><strong>- 01 ly signature cocktail hoặc mocktail </strong></p>

<p style="text-align:justify"><strong>- 01 Gift voucher 500.000 đồng (&aacute;p dụng cho menu alacarte)</strong></p>

<p style="text-align:justify"><strong>- Giảm 15% tối đa 2.000.000 VNĐ tr&ecirc;n tất cả h&oacute;a đơn sử dụng dịch vụ A La Carte, trước thuế v&agrave; c&aacute;c ph&iacute; dịch vụ.</strong></p>

<p style="text-align:justify"><strong>- Mỗi thẻ chỉ được sử dụng 01 ưu đ&atilde;i/ lần đặt b&agrave;n v&agrave; một h&oacute;a&nbsp;đơn. KH&Ocirc;NG hỗ trợ t&aacute;ch bill, gh&eacute;p b&agrave;n.</strong></p>

<p style="text-align:justify">- Thời gian phục vụ: Mỗi ng&agrave;y 11h30-22h00 l Last order 21h45</p>

<p style="text-align:justify"><strong>- Sử dụng 01 voucher/ 01 thẻ th&agrave;nh vi&ecirc;n/ 01 b&agrave;n.&nbsp; Gi&aacute; đ&atilde; bao gồm VAT v&agrave; ph&iacute; phụ vụ.</strong></p>

<p style="text-align:justify">- Kh&aacute;ch h&agrave;ng phải xuất tr&igrave;nh m&atilde; voucher hợp lệ trước khi sử dụng dịch vụ.</p>

<p style="text-align:justify">- Voucher kh&ocirc;ng được quy đổi th&agrave;nh tiền mặt, kh&ocirc;ng ho&agrave;n lại tiền thừa v&agrave; kh&ocirc;ng d&ugrave;ng để mua voucher hoặc thẻ.</p>

<p style="text-align:justify">- Khi kh&aacute;ch h&agrave;ng mua thẻ tr&ecirc;n Hotdeal sẽ k&iacute;ch hoạt lu&ocirc;n thẻ, lần gần nhất khi Kh&aacute;ch h&agrave;ng sử dụng ưu đ&atilde;i khi đến nh&agrave; h&agrave;ng nh&acirc;n vi&ecirc;n sẽ đưa thẻ vật l&yacute; cho kh&aacute;ch.</p>

<p style="text-align:justify">- Kh&ocirc;ng &aacute;p dụng c&aacute;c ng&agrave;y Lễ, Tết, c&aacute;c ng&agrave;y lễ đặc biệt kh&aacute;c (14/02, 08/03, 20/10, 24/12,...) v&agrave; c&aacute;c ng&agrave;y c&oacute; sự kiện đăc biệt tại Nh&agrave; h&agrave;ng.</p>

<p style="text-align:justify">- Nh&agrave; h&agrave;ng c&oacute; quyền kiểm so&aacute;t điều khoản v&agrave; điều kiện.</p>

<p style="text-align:justify">- Thẻ c&oacute; hiệu lực 12 th&aacute;ng kể từ ng&agrave;y k&iacute;ch hoạt.</p>

<p style="text-align:justify">- Chỉ &aacute;p dụng tại nh&agrave; h&agrave;ng, kh&ocirc;ng &aacute;p dụng mua mang đi.</p>

<p style="text-align:justify">- C&oacute; thể linh động theo b&aacute;o c&aacute;o h&agrave;ng h&oacute;a mỗi ng&agrave;y tại Outlet.</p>

<p style="text-align:justify">- Sản phẩm tặng kh&ocirc;ng c&oacute; gi&aacute; trị quy đổi tiền mặt.</p>

<p style="text-align:justify">&nbsp; Kh&ocirc;ng &aacute;p dụng đồng thời với c&aacute;c chương tr&igrave;nh v&agrave; Menu đặc biệt kh&aacute;c tại nh&agrave; h&agrave;ng (Dimsum đồng gi&aacute;, Menu ăn trưa, Set menu đặc biệt,...).</p>

<p style="text-align:justify">- Chỉ &aacute;p dụng ưu đ&atilde;i khi kh&aacute;ch h&agrave;ng xuất tr&igrave;nh thẻ vật l&yacute; tại nh&agrave; h&agrave;ng.</p>

<p style="text-align:justify">- Kh&aacute;ch h&agrave;ng vui l&ograve;ng th&ocirc;ng b&aacute;o trước về dị ứng thực phẩm hoặc y&ecirc;u cầu ăn uống đặc biệt. Nh&agrave; h&agrave;ng sẽ hỗ trợ trong phạm vi c&oacute; thể.</p>

<p style="text-align:justify"><strong>- Thanh to&aacute;n online nhận ngay voucher điện tử.</strong></p>
</div>
        </div>$BODY$, 'POLICY', 'ACTIVE');
INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (106, 103, 'Trải Nghiệm Dịch Vụ & Điểm Nổi Bật: Membership Lai Towa - 1 Khách - 7 Ưu Đãi - Tầng 28 Sedona Suites', $BODY$<div class="tab-pane active first" id="chi-tiet">
