INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (109, 105, 'Chính Sách & Điều Kiện Sử Dụng: VTM Úc Châu - Massage Đả Thông Kinh Lạc Trị Liệu Đau Cổ Vai Gáy', $BODY$<div class="tab-pane active visible-sm visible-xs visible-md" id="dieu-kien">
        <div class="block__header  clearfix">
            <h3 class="block__title">Điều kiện sử dụng</h3>
        </div>
        <div class="block__content clearfix">
            <div class="wysiwyg">
<p style="text-align:justify">- Thời hạn sử dụng voucher: <strong>từ 20/06/2026 đến 20/09/2026.</strong></p>

<p style="text-align:justify">- Địa điểm sử dụng voucher: <strong>Viện Thẩm Mỹ &Uacute;c Ch&acirc;u</strong> - 719 L&ecirc; Hồng Phong, Phường 12, Quận 10. ĐT: 0908 161788 - 0938 780159.</p>

<p style="text-align:justify"><strong>- &Aacute;p dụng cho Trọn g&oacute;i dịch vụ Massage dưỡng sinh đả th&ocirc;ng kinh lạc trị liệu đau cổ, vai, g&aacute;y giảm đau nhức tức th&igrave; hiệu quả ngay lần đầu ti&ecirc;n + Massage đầu + Đ&aacute; n&oacute;ng + Ấn huyệt cổ, vai, g&aacute;y giảm stress, k&iacute;ch th&iacute;ch kh&iacute; huyết lưu th&ocirc;ng v&agrave; trẻ h&oacute;a da (45 ph&uacute;t) tại Viện Thẩm Mỹ &Uacute;c Ch&acirc;u.</strong></p>

<p style="text-align:justify">- &Aacute;p dụng v&agrave;o tất cả c&aacute;c ng&agrave;y trong tuần. Giờ &aacute;p dụng: 9h-19h.</p>

<p style="text-align:justify"><strong>- &Aacute;p dụng cho cả nam v&agrave; nữ. C&oacute; ph&ograve;ng ri&ecirc;ng cho cặp đ&ocirc;i kh&ocirc;ng phụ thu.&nbsp; </strong></p>

<p style="text-align:justify">- Một kh&aacute;ch h&agrave;ng được mua nhiều phiếu.</p>

<p style="text-align:justify"><strong>- Sử dụng 01 phiếu/ 01 người/ 01 g&oacute;i dịch vụ (Kh&ocirc;ng b&ugrave; tiền).</strong></p>

<p style="text-align:justify">- Kh&ocirc;ng &aacute;p dụng đồng thời với c&aacute;c chương tr&igrave;nh khuyến m&atilde;i kh&aacute;c.</p>

<p style="text-align:justify">- Kh&aacute;ch h&agrave;ng vui l&ograve;ng đặt chỗ trước khi đến để được phục vụ tốt nhất.</p>

<p style="text-align:justify">- Phiếu kh&ocirc;ng c&oacute; gi&aacute; trị quy đổi th&agrave;nh tiền mặt, kh&ocirc;ng trả lại tiền thừa.</p>

<p style="text-align:justify"><strong>- Thanh to&aacute;n online nhận ngay voucher điện tử.</strong></p>
</div>
