INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (111, 106, 'Chính Sách & Điều Kiện Sử Dụng: Suki Nails Studio - Gội Đầu + Massage Cổ Vai Gáy + Ngâm Châm 60P', $BODY$<div class="tab-pane active visible-sm visible-xs visible-md" id="dieu-kien">
        <div class="block__header  clearfix">
            <h3 class="block__title">Điều kiện sử dụng</h3>
        </div>
        <div class="block__content clearfix">
            <div class="wysiwyg">
<p style="text-align:justify">- Thời hạn sử dụng voucher: <strong>từ 04/06/2026 đến 04/09/2026.</strong></p>

<p style="text-align:justify">- Địa điểm sử dụng voucher: <strong>Suki Nails Studio</strong>&nbsp;&ndash; 136/5 Trần Quang Diệu, Phường Nhi&ecirc;u Lộc, TP Hồ Ch&iacute; Minh.</p>

<p style="text-align:justify">- Hotline: 0908 162 455&nbsp;&ndash; Qu&yacute; kh&aacute;ch đặt dịch vụ trước khi đến sử dụng dịch vụ.</p>

<p style="text-align:justify">- Fanpage: <a href="https://www.facebook.com/sukinailsstudio2107" rel="nofollow" target="_blank" rel="nofollow">https://www.facebook.com/sukinailsstudio2107</a></p>

<p style="text-align:justify"><strong>- &Aacute;p dụng g&oacute;i dịch vụ Combo Y&ecirc;u bản th&acirc;n +&nbsp; 60 ph&uacute;t tại Suki Nails Studio.</strong></p>

<p style="text-align:justify"><strong>- G&oacute;i Combo thư gi&atilde;n y&ecirc;u bản th&acirc;n - 60 ph&uacute;t: Gội đầu thảo dược thư gi&atilde;n giảm căng thẳng + Massage trị liệu cổ vai g&aacute;y giảm đau mỏi vai g&aacute;y + Ủ dưỡng t&oacute;c với tinh chất thi&ecirc;n nhi&ecirc;n gi&uacute;p mềm mượt + Đắp mặt nạ dưỡng da + Ng&acirc;m ch&acirc;n thảo dược thi&ecirc;n nhi&ecirc;n gi&uacute;p lưu th&ocirc;ng kh&iacute; huyết xua tan mệt mỏi.</strong></p>

<p style="text-align:justify">- &Aacute;p dụng v&agrave;o tất cả c&aacute;c ng&agrave;y trong tuần.</p>

<p style="text-align:justify">- Thời gian &aacute;p dụng: 8h30 - 19h thứ 2 đến Chủ nhật tất cả c&aacute;c ng&agrave;y kể cả lễ tết.</p>

<p style="text-align:justify"><strong>- &Aacute;p dụng cho nam v&agrave; nữ, couple.</strong></p>

<p style="text-align:justify"><strong>- Sử dụng 01 phiếu/ 01 người/ g&oacute;i dịch vụ (Kh&ocirc;ng b&ugrave; tiền).</strong></p>

<p style="text-align:justify"><strong>- Gi&aacute; voucher chưa bao gồm Tips.</strong></p>

<p style="text-align:justify">- Một kh&aacute;ch h&agrave;ng được mua nhiều phiếu.</p>

<p style="text-align:justify">- Kh&ocirc;ng &aacute;p dụng đồng thời với c&aacute;c chương tr&igrave;nh khuyến m&atilde;i kh&aacute;c.</p>

<p style="text-align:justify">- Kh&aacute;ch h&agrave;ng vui l&ograve;ng đặt chỗ trước khi đến để được phục vụ tốt nhất.</p>

<p style="text-align:justify">- Phiếu kh&ocirc;ng c&oacute; gi&aacute; trị quy đổi th&agrave;nh tiền mặt, kh&ocirc;ng trả lại tiền thừa.</p>

<p style="text-align:justify"><strong>- Thanh to&aacute;n online nhận ngay voucher điện tử.</strong></p>
</div>
        </div>$BODY$, 'POLICY', 'ACTIVE');
INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (112, 106, 'Trải Nghiệm Dịch Vụ & Điểm Nổi Bật: Suki Nails Studio - Gội Đầu + Massage Cổ Vai Gáy + Ngâm Châm 60P', $BODY$<div class="tab-pane active first" id="chi-tiet">
        <div class="block__header  clearfix">
            <h3 class="block__title">Thông tin chi tiết</h3>
        </div>
        <div class="block__content clearfix">
            <div class="wysiwyg">
    <p style="text-align:justify">Sau những ng&agrave;y bận rộn với c&ocirc;ng việc, học tập v&agrave; cuộc sống, cơ thể rất cần được nghỉ ngơi v&agrave; t&aacute;i tạo năng lượng. Thay v&igrave; chỉ chăm s&oacute;c vẻ ngo&agrave;i, h&atilde;y d&agrave;nh cho bản th&acirc;n những ph&uacute;t gi&acirc;y thư gi&atilde;n trọn vẹn để cơ thể v&agrave; tinh thần c&ugrave;ng được nu&ocirc;ng chiều. Tại Suki Nails Studio, Combo Thư Gi&atilde;n Y&ecirc;u Bản Th&acirc;n 60 ph&uacute;t l&agrave; lựa chọn l&yacute; tưởng gi&uacute;p bạn xua tan căng thẳng, giảm mệt mỏi v&agrave; lấy lại cảm gi&aacute;c nhẹ nh&agrave;ng, thư th&aacute;i. Liệu tr&igrave;nh được kết hợp h&agrave;i h&ograve;a giữa chăm s&oacute;c t&oacute;c, dưỡng da v&agrave; thư gi&atilde;n cơ thể, mang đến trải nghiệm chăm s&oacute;c to&agrave;n diện.</p>

<p style="text-align:justify">&nbsp;</p>

<p style="text-align:center"><img class="lazy" src="data:image/gif;base64,R0lGODlhAQABAIAAAMLCwgAAACH5BAAAAAAALAAAAAABAAEAAAICRAEAOw==" data-src-mobile="" data-original="https://oms.hotdeal.vn/images/editors/sources/000371157066/371157-371157-body-chung(8).jpg" /></p>

<p style="text-align:center">&nbsp;</p>

