INSERT INTO popups (popup_id, program_id, title, content, target_url, image_url, start_at, end_at, status) VALUES (107, 107, '🔥 Săn Deal Hot: Công viên Du lịch Văn hóa Suối Tiên', 'Ưu đãi giảm giá 12% cho chương trình "Suối Tiên - Combo Vé Cổng + Trò Chơi Biển Tiên Đồng - Ngọc N". Số lượng có hạn!', '/vouchers/107', 'https://static.hotdeal.vn/images/1736/1736064/800x800/371249-suoi-tien-combo-ve-cong-tro-choi-bien-tien-dong-ngoc-nu.jpg', '2026-08-22T08:00:00.000Z', '2026-09-21T08:00:00.000Z', 'ACTIVE');
INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (113, 107, 'Chính Sách & Điều Kiện Sử Dụng: Suối Tiên - Combo Vé Cổng + Trò Chơi Biển Tiên Đồng - Ngọc Nữ', $BODY$<div class="tab-pane active visible-sm visible-xs visible-md" id="dieu-kien">
        <div class="block__header  clearfix">
            <h3 class="block__title">Điều kiện sử dụng</h3>
        </div>
        <div class="block__content clearfix">
            <div class="wysiwyg">
<p style="text-align:justify">- Thời hạn sử dụng:&nbsp;<strong>từ 02/07/2026 đến 02/01/2027.</strong></p>

<p style="text-align:justify">- Địa điểm sử dụng voucher:&nbsp;<strong>C&ocirc;ng vi&ecirc;n Du lịch Văn h&oacute;a Suối Ti&ecirc;n</strong>&nbsp;&ndash; 120 Xa Lộ H&agrave; Nội, Phường Tăng Nhơn Ph&uacute;, Tp.HCM - Hotline: 1900 636 787 &ndash; 028 38960260.</p>

<p style="text-align:justify"><strong>- Voucher &aacute;p dụng cho: Combo v&eacute; cổng, tham quan v&agrave; vui chơi c&ugrave;ng c&ocirc;ng vi&ecirc;n nước cho người lớn &amp; trẻ em</strong></p>

<p style="text-align:justify"><strong>1. Combo Tham Quan + C&ocirc;ng Vi&ecirc;n Nước Cho Trẻ Em ưu đ&atilde;i giảm chỉ c&ograve;n 255.000đ (gi&aacute; gốc 290.000đ).</strong></p>

<p style="text-align:justify"><strong>2. Combo Kh&aacute;m Ph&aacute; + C&ocirc;ng Vi&ecirc;n Nước Cho Trẻ Em ưu đ&atilde;i giảm chỉ c&ograve;n 300.000đ (gi&aacute; gốc 360.000đ).</strong></p>

<p style="text-align:justify"><strong>3. Combo Tham Quan + C&ocirc;ng Vi&ecirc;n Nước Cho Người Lớn ưu đ&atilde;i giảm chỉ c&ograve;n 375.000đ (gi&aacute; gốc 455.000đ).</strong></p>

<p style="text-align:justify"><strong>4. Combo Kh&aacute;m Ph&aacute; + C&ocirc;ng Vi&ecirc;n Nước Cho Người Lớn ưu đ&atilde;i giảm chỉ c&ograve;n 450.000đ (gi&aacute; gốc 560.000đ)</strong></p>

<p style="text-align:justify"><strong>5. Combo Thử Th&aacute;ch + C&ocirc;ng Vi&ecirc;n Nước Cho Người Lớn ưu đ&atilde;i giảm chỉ c&ograve;n 450.000đ (gi&aacute; gốc 560.000đ).</strong></p>

<p style="text-align:justify"><strong>- Combo tr&ograve; chơi bao gồm:</strong></p>

<p style="text-align:justify"><strong>1. Combo Tham Quan + C&ocirc;ng Vi&ecirc;n Nước: </strong>V&eacute; cổng + Xe lửa + Massage C&aacute; + Vương Quốc C&aacute; Sấu + Sản Phẩm Suối Ti&ecirc;n Farm + Cung V&agrave;ng Điện Ngọc + Biển Ti&ecirc;n Đồng - Ngọc Nữ.</p>

<p style="text-align:justify"><strong>2. Combo Kh&aacute;m Ph&aacute; + C&ocirc;ng Vi&ecirc;n Nước:</strong> V&eacute; Cổng + Taxi + Kỳ L&acirc;n Cung + L&acirc;u Đ&agrave;i Tuyết + Cung Đ&igrave;nh Tửu + B&iacute; Mật Rừng Ph&ugrave; Thủy + Cối Xay Thần Gi&oacute; + Du Thuyền Tứ Linh + Biển Ti&ecirc;n Đồng - Ngọc Nữ.</p>

<p style="text-align:justify"><strong>3. 4. Combo Thử Th&aacute;ch + C&ocirc;ng Vi&ecirc;n Nước: </strong>V&eacute; Cổng + Xe Lửa + Đĩa Bay H&agrave;nh Tinh Lạ + T&agrave;u Lượn Si&ecirc;u Tốc + V&ograve;ng Xoay Vũ Trụ + Kh&aacute;m Ph&aacute; Vũ Trụ Huyền B&iacute; + Thuyền Bay hoặc Thuyền Rồng + Biển Ti&ecirc;n Đồng - Ngọc Nữ.</p>

<p style="text-align:justify">- Giờ hoạt động: 8h &ndash; 17h. Voucher &aacute;p dụng tất cả c&aacute;c ng&agrave;y trong tuần, bao gồm cả lễ, tết.</p>

<p style="text-align:justify"><strong>- Sử dụng 01 voucher/01 người (kh&ocirc;ng b&ugrave; th&ecirc;m tiền).</strong></p>

<p style="text-align:justify"><strong>- Quy định t&iacute;nh v&eacute;:</strong></p>

<p style="text-align:justify">+ Dưới 1m: Miễn v&eacute; (Trừ c&aacute;c tr&ograve; chơi tại khu Mega Zone)</p>

<p style="text-align:justify">+ Từ 1m đến dưới 1m4: &Aacute;p dụng gi&aacute; v&eacute; d&agrave;nh cho trẻ em</p>

<p style="text-align:justify">+ Từ 1m4 trở l&ecirc;n: &Aacute;p dụng gi&aacute; v&eacute; d&agrave;nh cho người lớn</p>

<p style="text-align:justify"><strong>- C&aacute;ch thức đổi v&eacute; E-Voucher: Kh&aacute;ch h&agrave;ng xuất tr&igrave;nh m&atilde; code được Hotdeal gửi qua SMS, Email hoặc trong ứng dụng Hotdeal tại quầy v&eacute; Suối Ti&ecirc;n.</strong></p>

<p style="text-align:justify">- Một kh&aacute;ch h&agrave;ng được mua nhiều phiếu.</p>

<p style="text-align:justify">- Kh&ocirc;ng &aacute;p dụng đồng thời với c&aacute;c chương tr&igrave;nh khuyến m&atilde;i kh&aacute;c.</p>

<p style="text-align:justify">- Phiếu kh&ocirc;ng c&oacute; gi&aacute; trị quy đổi th&agrave;nh tiền mặt, kh&ocirc;ng trả lại tiền thừa.</p>

<p style="text-align:justify"><strong>- Thanh to&aacute;n online nhận ngay voucher điện tử.</strong></p>
</div>
        </div>$BODY$, 'POLICY', 'ACTIVE');
INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (114, 107, 'Trải Nghiệm Dịch Vụ & Điểm Nổi Bật: Suối Tiên - Combo Vé Cổng + Trò Chơi Biển Tiên Đồng - Ngọc Nữ', $BODY$<div class="tab-pane active first" id="chi-tiet">
        <div class="block__header  clearfix">
            <h3 class="block__title">Thông tin chi tiết</h3>
        </div>
        <div class="block__content clearfix">
            <div class="wysiwyg">
    <p style="text-align:justify">Nằm trong C&ocirc;ng vi&ecirc;n Du lịch Văn h&oacute;a Suối Ti&ecirc;n, Biển Ti&ecirc;n Đồng &ndash; Ngọc Nữ l&agrave; biển nh&acirc;n tạo đầu ti&ecirc;n tại Việt Nam, với kiến tr&uacute;c m&ocirc; phỏng truyền thuyết Lạc Long Qu&acirc;n &ndash; &Acirc;u Cơ. Nơi đ&acirc;y được mệnh danh l&agrave; một kỳ quan h&ugrave;ng vĩ, một đại dương huyền thoại giữa l&ograve;ng th&agrave;nh phố. Trải nghiệm cảm gi&aacute;c m&aacute;t lạnh đầy sảng kho&aacute;i khi h&ograve;a m&igrave;nh v&agrave;o l&agrave;n nước trong xanh tại Biển Ti&ecirc;n Đồng - Ngọc Nữ v&agrave; tham gia hơn 30 tr&ograve; chơi dưới nước hiện đại sẽ đem đến cho bạn những cuộc vui kh&ocirc;ng thể n&agrave;o qu&ecirc;n.</p>

<p style="text-align:justify">&nbsp;</p>

<p style="text-align:center"><img class="lazy" src="data:image/gif;base64,R0lGODlhAQABAIAAAMLCwgAAACH5BAAAAAAALAAAAAABAAEAAAICRAEAOw==" data-src-mobile="" data-original="https://oms.hotdeal.vn/images/editors/sources/000370759525/370759-370757-body-1.jpg" /></p>

<p style="text-align:center">&nbsp;</p>

<p style="text-align:center"><img class="lazy" src="data:image/gif;base64,R0lGODlhAQABAIAAAMLCwgAAACH5BAAAAAAALAAAAAABAAEAAAICRAEAOw==" data-src-mobile="" data-original="https://oms.hotdeal.vn/images/editors/sources/000370758119/370758-370758-body-TET(9).jpg" style="text-align:center" /></p>

<p style="text-align:center">&nbsp;</p>

<p style="text-align:justify">Đặc biệt, qu&yacute; kh&aacute;ch chỉ cần l&ecirc;n Metro v&agrave; xuống Ga Đại học Quốc gia l&agrave; đến Suối Ti&ecirc;n rồi. Vừa nhanh, vừa tr&aacute;nh kẹt xe,&nbsp;kh&oacute;i bụi v&agrave; nhanh ch&oacute;ng bắt đầu h&agrave;nh tr&igrave;nh vui bất tận!&nbsp;</p>

<p style="text-align:center"><br />
<img class="lazy" src="data:image/gif;base64,R0lGODlhAQABAIAAAMLCwgAAACH5BAAAAAAALAAAAAABAAEAAAICRAEAOw==" data-src-mobile="" data-original="https://oms.hotdeal.vn/images/editors/sources/000369929902/369929-body-bs(1).jpg" /></p>

<p style="text-align:center">&nbsp;</p>

<p style="text-align:center"><img class="lazy" src="data:image/gif;base64,R0lGODlhAQABAIAAAMLCwgAAACH5BAAAAAAALAAAAAABAAEAAAICRAEAOw==" data-src-mobile="" data-original="https://oms.hotdeal.vn/images/editors/sources/000369929902/369929-body-bs(2).jpg" style="text-align:center" /></p>

